struct JvmCdRow {
    int present;
    std::uint64_t aicc, bic, ssq;
    int nx, dof, dim;
};
struct JvmCdCmpCase {
    const char* id;
    const JvmCdRow* rows;
    int nrows;
    std::uint64_t pmodel, pconstraint;   // waldTest wiring (inputs.csv)
    int bestaicc, bestbic, wald;
};

struct JvmCdCand {
    const char* tag;
    const std::uint64_t* coef;
    int ncoef;
    const std::uint64_t* covdiag;
    int ncov;
    std::uint64_t ssq;
    int dim, dof, nx, k;
    int td_pos, lp_pos, ea_pos;   // -1 = not a variable of the candidate
    int nhp, curk, curmean, mean, adj, log;
    const char* prespec;
    const char* spec;
};
struct JvmCdLadderCase {
    const char* id;
    int sa;                       // 0 = TRAMO TA, 1 = sa SA
    int selector;                 // 0 aicc 1 bic 2 wald
    std::uint64_t pmodel, pconstraint, tlp;   // raw bits
    int adjust, testmean, has_easter, has_lp;
    const JvmCdRow* rows;
    int nrows;
    JvmCdCand cands[8];           // r0..r7; absent rows keep the echo
    int sa_td_present, sa_lp_present, sa_adj, sa_log;
    int sa_equals[8];
    int sa_nequals;
    int bestaicc, bestbic, wald;  // the jar comparator echoes
    int det_atd_best;             // jar ATD Info; -999 = not logged
    int result, mean_after;
    const char* vars_pre; const char* vars_after;
};

struct JvmCdFtestCase {
    const char* id;
    std::uint64_t fpvalue;
    int has_easter, testmean, adjust;
    JvmCdCand info_none, info_td, info_wd;   // the Info rows (no lp)
    JvmCdCand upd_td, upd_wd;                // the update models (with lp)
    int info_seen;                           // det FT journal row present
    std::uint64_t ss0, ss1, ss6, ssmc1, ssmc6, pftd1, pftd6;
    int info_nhp;
    int result, mean_after;
    const char* vars_after;
};

struct JvmCdSlot {
    int pos, dim;                 // -1/0 = the slot is empty
};
struct JvmCdClc {
    const std::uint64_t* coef;
    int ncoef;
    const std::uint64_t* covdiag;
    int ncov;
    std::uint64_t ssq;
    int dim, dof, nx, k;
};
struct JvmCdFastStep {
    const char* id;
    std::uint64_t tmean, tvar;
    int testmean;
    JvmCdClc clc;
    JvmCdSlot td, lp, mh;
    int desc_mean;
    int result, mean_after, est_set;   // est_set 0: the jar cleared it
    const char* vars_pre; const char* vars_after;
};

struct JvmCdCovRow {
    const std::uint64_t* bits;
    int n;
};
struct JvmCdDefaultStep {
    const char* id;
    std::uint64_t tmean;
    int testmean, adjust, join;
    JvmCdClc dtc;                        // the test-model cl
    const JvmCdCovRow* cov;              // dtu lower triangle rows
    int ncov;
    JvmCdSlot td, lp, ea;
    int desc_test_log, regarima_mean, desc_mean;
    int jt_q, jt_df;                     // jt echo; jt_q 0 = absent
    std::uint64_t jt_value, jt_pvalue;
    int result, mean_after, est_set;
    const char* vars_pre; const char* vars_after;
};

struct JvmCdJointCase {
    const char* id;
    int pos, q, k;
    JvmCdClc clc;
    const JvmCdCovRow* cov;
    int ncov;
    std::uint64_t value, pvalue;
};

struct JvmCdPipeCase {
    const char* id;
    int px;                              // 0 PT (TRAMO), 1 PX (X13)
    const char* method;
    int run_ok;                          // run OK set
    const char* tdspec;                  // the wiring witness line
};

